SELECT FROM managed_document WHERE deleted = FALSE AND status = #{status}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR raw_content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY created_at DESC, id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM managed_document
WHERE active_content_hash = #{contentHash}
AND id <> #{excludedId}
